    import {
      Column,
      Entity,
      PrimaryGeneratedColumn,
      OneToMany,
      JoinColumn,
    } from "typeorm";
    import { Student } from "./student.entity";

    @Entity()
    export class Classes {
      @PrimaryGeneratedColumn()
      id: number = 0;

      @Column()
      name: string = "";

      @Column()
      type: string = "";

      @OneToMany(() => Student, (student) => student.classes)
      @JoinColumn()
      studentList: Student[];
    }
    ```

  - 学生表

    ```js
    import {
      Column,
      Entity,
      PrimaryGeneratedColumn,
      ManyToOne,
