  // 获取公共组件
  export function generateComponent(conf: TBasicComponentConfig) {
    const Component = getComponentByType(conf.type);

    // toJS将mobx装饰过的对象转成普通对象
    return <Component {...toJS(conf.props)} key={conf.id} />;
