                { header: [1, 2, 3, 4, false] },
                "bold",
                "italic",
                "underline",
                { color: [] },
                { background: [] },
                { align: [] },
                { list: "ordered" },
                { list: "bullet" },
                { font: [] },
              ],
              ["code-block"],
            ],
          }}
          placeholder="请输入内容"
